/**
 * Blog/project categories, keyed by a stable id. Content references them by key
 * (`categories: [dr-kongo]` in frontmatter); the schema rejects unknown keys.
 *
 * Generated by scripts/migrate-wp from the WordPress categories (Polylang translations merged,
 * the colour came from the WordPress description field). Re-running the migration overwrites
 * this file; after cutover edit it by hand.
 *
 * - label: shown on cards and the post header, per language
 * - color: colour of the dot next to the label (cards fall back to the brand colours)
 * - isPress: press releases (listed on /presse/)
 * - status: project status categories (projects use the `status` field instead)
 * - product: filter product categories (projects use the `filters` field instead)
 */
import type { Locale } from '@/i18n';

export interface Category {
  label: Record<Locale, string>;
  color?: string;
  isPress?: boolean;
  status?: 'in-progress' | 'completed';
  product?: 'aqqabag' | 'aqqacube' | 'aqqasystem';
}

const categoryData = {
  abgeschlossen: { label: { de: "Abgeschlossen", en: "Completed", fr: "Achevé" }, status: "completed" },
  allgemein: { label: { de: "Allgemein", en: "General", fr: "Général" }, color: "#5ABEE6" },
  "aqqabag-projekt": { label: { de: "AQQAbag-Projekt", en: "AQQAbag project", fr: "Projet AQQAbag" }, product: "aqqabag" },
  "aqqacube-projekt": { label: { de: "AQQAcube-Projekt", en: "AQQAcube-project", fr: "Projet AQQAcube" }, product: "aqqacube" },
  belutschistan: { label: { de: "Belutschistan", en: "Balochistan", fr: "Baloutchistan" } },
  bweyale: { label: { de: "Bweyale", en: "Bweyale", fr: "Bweyale" }, color: "#7E5AE6" },
  "dr-kongo": { label: { de: "DR Kongo", en: "DR Congo", fr: "RD Congo" } },
  "in-arbeit": { label: { de: "In Arbeit", en: "In progress", fr: "En réalisation" }, status: "in-progress" },
  "kenia-projekte-2020": { label: { de: "Kenia Projekte 2020", en: "Kenya Projects 2020", fr: "Projets Kenya 2020" }, color: "#E6955A" },
  "kenia-projekte-2021": { label: { de: "Kenia Projekte 2021", en: "Kenya Projects 2021", fr: "Projets Kenya 2021" }, color: "#E6955A" },
  lichtstrahl: { label: { de: "Lichtstrahl", en: "Lightray", fr: "Rayon lumineux" }, color: "#74E3A2" },
  lwamaggwa: { label: { de: "Lwamaggwa", en: "Lwamaggwa", fr: "Lwamaggwa" } },
  presse: { label: { de: "Presse", en: "Press", fr: "Presse" }, color: "#E65A74", isPress: true },
  projekte: { label: { de: "Projekte", en: "Projects", fr: "Projets" } },
  "uganda-projekte-2022": { label: { de: "Uganda Projekte 2022", en: "Uganda Projects 2022", fr: "Projets Ouganda 2022" } },
  veranstaltungen: { label: { de: "Veranstaltungen", en: "Events", fr: "Événements" } },
} satisfies Record<string, Category>;

export type CategoryKey = keyof typeof categoryData;

export const categories: Record<CategoryKey, Category> = categoryData;

export const categoryKeys = Object.keys(categoryData) as [CategoryKey, ...CategoryKey[]];

/** Label of a category in the given language. */
export function categoryLabel(key: CategoryKey, locale: Locale): string {
  return categories[key].label[locale];
}
